/// <summary>
///     The <c>AVADirPartyQuickCreateFormFrm_DirPartyTableDS_Extension</c> class is the extension for <c>DirPartyQuickCreateForm</c>
/// </summary>
[ExtensionOf(FormDatasourceStr(DirPartyQuickCreateForm, DirPartyTable))]
final class AVADirPartyQuickCreateFormFrm_DirPartyTableDS_Extension
{
}

Method.Source:
/// <summary>
///    AVA <c>validateWrite</c> method.
/// </summary>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean validateWrite()
{
    boolean ret;
    boolean retTmp;

    ret     = true;
    retTmp  = true;

    if(element.dirPartyTable.partyType() == DirPartyType::Person)
    {
        if (!element.dirPersonName.LastName)
        {
            // A last name is required.
            retTmp = checkFailed("@SYS81632");
        }
    }

    ret = next validateWrite();

    return ret && retTmp;
}

/// <summary>
/// designed from N.Freidenberger 14.05.2024
/// </summary>
public void initValue()
{
    next initValue();

    if (element.args().menuItemName() ==  menuItemDisplayStr(AVAsmmBusRelQuickCopy))
    {
        smmBusRelTable      copySmmBusRelTable = element.args().record();
        DirPartyTable       copyDirPartyTable  = copySmmBusRelTable.dirPartyTable();
        DirPartyTable       newDirPartyTable   = this.cursor();

        newDirPartyTable.Name      = copyDirPartyTable.Name;
    }
}
